<!DOCTYPE html>
<html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>Login — JIBIKA</title><script src="https://cdn.tailwindcss.com"></script></head><body class="bg-[#f8fafc] min-h-screen flex items-center justify-center"><div class="bg-white rounded-3xl shadow-lg p-10 max-w-md w-full ring-1 ring-slate-900/5"><h1 class="text-2xl font-extrabold mb-6 text-[#127A4A]">Sign In</h1><form method="POST" action="/login" class="space-y-4"><input type="hidden" name="_token" value="{{ csrf_token() }}"><input name="email" type="email" placeholder="Email" class="w-full px-4 py-3 rounded-xl border border-slate-200 focus:outline-none focus:ring-2 focus:ring-[#127A4A]/20"><input name="password" type="password" placeholder="Password" class="w-full px-4 py-3 rounded-xl border border-slate-200 focus:outline-none focus:ring-2 focus:ring-[#127A4A]/20"><button type="submit" class="w-full py-3.5 rounded-xl bg-[#127A4A] text-white font-semibold hover:bg-[#0e5a36] transition">Sign In</button></form></div></body></html>
